begin;
select no_plan();
select ok(not has_function_privilege('anon','api.execute_owner_catalog_search_server(uuid,text,jsonb)','execute'),'Anonymous search denied');
select ok(not has_function_privilege('authenticated','api.execute_owner_catalog_search_server(uuid,text,jsonb)','execute'),'Browser cannot select subject');
select ok(has_function_privilege('service_role','api.execute_owner_catalog_search_server(uuid,text,jsonb)','execute'),'Fixed server search admitted');
select ok(not has_function_privilege('service_role','api.resolve_current_owner_spill_manager_filtered(jsonb)','execute'),'Original search closed');
select ok(not has_table_privilege('service_role','core.workspace_item_sources','SELECT'),'Raw source view stays closed');
set local role authenticated;
select throws_ok($$select api.execute_owner_catalog_search_server(null,null,'{}')$$,'42501',null,'Actual browser call denied');
reset role;
insert into auth.users(id,email) values('27900000-0000-4000-8000-000000000001','starter-one@example.test'),('27900000-0000-4000-8000-000000000002','starter-two@example.test');
create temporary table actors as select auth_user_id,owner_id from core.owner_auth_bindings where auth_user_id in('27900000-0000-4000-8000-000000000001','27900000-0000-4000-8000-000000000002');
update core.owners set onboarding_completed_at=now() where id in(select owner_id from actors);
update core.owner_onboarding_progress set current_step='preview_publish',primary_use_case='personal' where owner_id in(select owner_id from actors);
insert into core.owner_handle_namespaces(normalized_handle,owner_id,namespace_kind) select 'catalog279-'||right(auth_user_id::text,6),owner_id,'current' from actors;
insert into core.identity_working(owner_id,display_name,revision) select owner_id,'Identity',1 from actors;
insert into core.identity_layout_working(owner_id,starter_key,revision) select owner_id,'clean',1 from actors;
insert into core.product_drafts(owner_id,source_url,title,revision) select owner_id,'https://shop.example.test/product',case when right(auth_user_id::text,1)='1' then 'First product' else 'Foreign product' end,2 from actors;
insert into core.resource_drafts(owner_id,resource_type,source_url,title,revision) select owner_id,'document','https://resource.example.test/document','Original resource',2 from actors;
insert into core.product_preparations(product_id,owner_id,destinations,revision) select id,owner_id,'[{"provider_key":"external:shop.example.test","destination_url":"https://shop.example.test/product"}]',4 from core.product_drafts where owner_id in(select owner_id from actors);
insert into core.spill_item_publications(item_id,owner_id,item_type,spill_reference,working_revision,snapshot,lifecycle_state,published_at)
 select item_id,owner_id,item_type,spill_reference,2,'{"original":true}','hidden',now() from core.spill_item_identity_registry where owner_id in(select owner_id from actors) and item_type='resource';

insert into core.workspace_resource_drafts(owner_id,creation_id,resource_type,title)
 select owner_id,gen_random_uuid(),'document','Needle Resource '||n from actors cross join generate_series(1,27) n where right(auth_user_id::text,1)='1';
insert into core.starter_item_working(item_id,owner_id,item_type,spill_reference,title,source_url,resource_type,source_revision,revision)
 select item_id,owner_id,item_type,spill_reference,'100% _ Working',null,null,2,1 from core.spill_item_identity_registry where owner_id=(select owner_id from actors where right(auth_user_id::text,1)='1') and item_type='product';
create temporary table baseline as select (select count(*) from core.spill_item_identity_registry where owner_id in(select owner_id from actors)) reserved,(select jsonb_agg(to_jsonb(p)) from core.spill_item_publications p where owner_id in(select owner_id from actors)) published;
create function pg_temp.search(subject uuid,q text default '',kind text default 'all',lifecycle text default 'all',cursor bigint default null) returns jsonb language sql as $$
 select api.execute_owner_catalog_search_server(subject,'resolve_current_owner_spill_manager_filtered',jsonb_build_object('input_filter',jsonb_build_object('q',q,'kind',kind,'lifecycle',lifecycle,'before',cursor)));
$$;
grant execute on function pg_temp.search(uuid,text,text,text,bigint) to service_role;
set local request.jwt.claims='{"role":"service_role","sub":"27900000-0000-4000-8000-000000000002"}';
set local request.jwt.claim.sub='27900000-0000-4000-8000-000000000002';
set local role service_role;
select is(jsonb_array_length(pg_temp.search('27900000-0000-4000-8000-000000000001','nEeDlE','resource','draft')->'items'),20,'Case-insensitive combined scope bounded to20');
select is(pg_temp.search('27900000-0000-4000-8000-000000000001','Needle','resource','draft')->>'next_before_reference','10','Filtered seek cursor from twentieth match');
select is(jsonb_array_length(pg_temp.search('27900000-0000-4000-8000-000000000001','Needle','resource','draft',10)->'items'),7,'Second seek page has remaining matches');
select is(pg_temp.search('27900000-0000-4000-8000-000000000001','Needle','resource','draft',10)->>'has_more','false','No phantom third page');
select is(jsonb_array_length(pg_temp.search('27900000-0000-4000-8000-000000000002','Needle')->'items'),0,'Foreign catalog never searched');
select is(jsonb_array_length(pg_temp.search('27900000-0000-4000-8000-000000000001','First product')->'items'),0,'Saved Working override shadows immutable source title');
select is(jsonb_array_length(pg_temp.search('27900000-0000-4000-8000-000000000001','100% _')->'items'),1,'Wildcard characters treated literally');
select is(jsonb_array_length(pg_temp.search('27900000-0000-4000-8000-000000000001','%nope')->'items'),0,'Percent does not widen title search');
select is(jsonb_array_length(pg_temp.search('27900000-0000-4000-8000-000000000001','#1')->'items'),1,'Exact reference selected');
select is(pg_temp.search('27900000-0000-4000-8000-000000000001','#1')->'items'->0->>'kind','product','Shared reference selects correct type');
select is(jsonb_array_length(pg_temp.search('27900000-0000-4000-8000-000000000001','#1','resource')->'items'),0,'Active type filter remains effective for exact query');
select is(jsonb_array_length(pg_temp.search('27900000-0000-4000-8000-000000000001','#01')->'items'),0,'Malformed exact reference never falls back');
select is(jsonb_array_length(pg_temp.search('27900000-0000-4000-8000-000000000001','9007199254740992')->'items'),0,'Unsafe integer cannot round to another reference');
select is(jsonb_array_length(pg_temp.search('27900000-0000-4000-8000-000000000001','','resource','hidden')->'items'),1,'Hidden Resources remain manageable');
select is(jsonb_array_length(pg_temp.search('27900000-0000-4000-8000-000000000001','','product','draft')->'items'),1,'Draft means no Published lifecycle, independent of Working');
select ok(not ((pg_temp.search('27900000-0000-4000-8000-000000000001','100%')->'items'->0)?'source_url'),'No destination or source in manager DTO');
select is(pg_temp.search('27900000-0000-4000-8000-000000000001','  Needle')->>'status','unavailable','Noncanonical scope refused');
select is(pg_temp.search('27900000-0000-4000-8000-000000000001',repeat('x',81))->>'status','unavailable','Oversized query refused');
select is(pg_temp.search('27900000-0000-4000-8000-000000000001','','all','needs_attention')->>'status','unavailable','Health is not a lifecycle');
select is(api.execute_owner_catalog_search_server('27900000-0000-4000-8000-000000000001','publish_current_onboarding','{}')->>'status','unavailable','Arbitrary operation denied');
select is(api.execute_owner_catalog_search_server('27900000-0000-4000-8000-000000000001','resolve_current_owner_spill_manager_filtered','{"input_filter":{},"owner_id":"forged"}')->>'status','unavailable','Owner envelope injection denied');
select is(current_setting('request.jwt.claim.sub'),'27900000-0000-4000-8000-000000000002','Subject restored after searches/denials');
reset role;
update core.starter_item_working set title='' where owner_id=(select owner_id from actors where right(auth_user_id::text,1)='1');
set local role service_role;
select is(jsonb_array_length(pg_temp.search('27900000-0000-4000-8000-000000000001','100%')->'items'),0,'Explicit blank Working title does not resurrect source');
reset role;
update core.owners set account_state='restricted' where id=(select owner_id from actors where right(auth_user_id::text,1)='1');
set local role service_role;
select is(pg_temp.search('27900000-0000-4000-8000-000000000001')->>'status','unavailable','Restricted Owner cannot search');
reset role;
select is((select count(*) from core.spill_item_identity_registry where owner_id in(select owner_id from actors)),(select reserved from baseline),'Search allocates no references');
select is((select jsonb_agg(to_jsonb(p)) from core.spill_item_publications p where owner_id in(select owner_id from actors)),(select published from baseline),'Search changes no public lifecycle/snapshot');
select * from finish();
rollback;
